mapper.select:
SELECT * FROM board.comment
ORDER BY created_at DESC
LIMIT #{pageSize}
OFFSET #{offset}

SELECT c.comment_plus_no, c.comment_content, c.created_at, u.user_nick AS userNick
FROM comment c
JOIN user u ON c.user_id = u.user_id
WHERE c.comment_plus_no = #{commentPlusNo}
ORDER BY c.created_at DESC
LIMIT #{pageSize}
OFFSET #{offset}

SELECT c.comment_no, c.comment_content, u.user_nick AS userNick
FROM comment c
JOIN user u ON c.user_id = u.user_id
WHERE u.user_nick = #{userNick}
ORDER BY c.created_at DESC
LIMIT #{pageSize}
OFFSET #{offset}

mapper.update:
UPDATE board.comment
SET comment_content = #{commentContent}
WHERE comment_no = #{commentNo}
AND user_id = #{userId}

    UPDATE board.comment
	SET is_deleted = true
	WHERE comment_no = #{commentNo}
